package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") long claimId,
            ClaimRepository repository, Out<Claim> claim) throws ClaimNotFoundException {
        Claim found = repository.find(sheetId, claimId);
        if (found == null) {
            throw new ClaimNotFoundException(claimId);
        }
        claim.set(found);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Refuses (400) a deferral unless the claim is OPEN and the date is after the sheet's today. */
public class CheckClaimDeferral {
    public void check(@Val Claim claim, @Val Deferral deferral, SheetRepository sheets) throws InvalidClaimException {
        if (claim.status() != ClaimStatus.OPEN) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be deferred.");
        }
        if (!deferral.until().isAfter(sheets.today(claim.sheetId()))) {
            throw new InvalidClaimException("A claim can only be deferred to a date after the sheet's today.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Defers the claim until the deferral's date. */
public class DeferClaim {
    public void defer(@Val Claim claim, @Val Deferral deferral, ClaimRepository repository, Out<Claim> deferred) {
        Claim next = claim.deferTo(deferral.until());
        repository.defer(next);
        deferred.set(next);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim just deferred, with its person's name, then the date it is deferred until. */
public class AuditClaimDeferred {
    public void audit(@Val Claim claim, PersonRepository people, @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_DEFERRED sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(claim.number()) + " until=" + claim.deferredUntil());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ClaimLogRepository logs, ClaimLockRepository locks,
            ClaimRepository repository, ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim, logs.find(claim.sheetId(), claim.id()),
                locks.lockedBy(claim.sheetId(), claim.id()),
                repository.lateEntry(claim.sheetId(), claim.id())));
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

/** Refuses (400) any change to an archived sheet: it runs first, so a refused change writes nothing. */
public class CheckNotArchived {
    public void check(@PathVariable("sheetId") String sheetId, SheetRepository sheets) throws SheetArchivedException {
        if (sheets.isArchived(sheetId)) {
            throw new SheetArchivedException("An archived sheet cannot be changed.");
        }
    }
}
package net.officefloor.hq.app.setting;

import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Refuses (400) any change by a viewer on the sheet: it runs first, so a refused change writes nothing. */
public class CheckNotViewer {
    public void check(@PathVariable("sheetId") String sheetId, @RequestParam("user") String user,
            SettingRepository settings) throws ViewerRefusedException {
        if (settings.find(sheetId).roleOf(user) == Role.VIEWER) {
            throw new ViewerRefusedException("A viewer cannot change the sheet.");
        }
    }
}

